import React, { useState } from 'react'
import { Link } from 'gatsby'
import styled from '@emotion/styled'
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'
import {
  faHouseChimney,
  faMagnifyingGlass,
} from '@fortawesome/free-solid-svg-icons'

import {
  useGetCategories,
  useFormatCategory,
  useSelectedCategory,
} from 'hooks/useCategories'
import { GatsbyLinkProps } from 'components/Main/CategoryList'
import { cssState } from 'constants/type'
import { color } from 'constants/color'
import SearchModal from './SearchModal'

const Wrap = styled.header<cssState>`
  z-index: 1;
  position: fixed;
  width: 100%;
  background-color: ${color.bg};
  box-shadow: 0 1px 0 ${color.border};
  opacity: ${props => (props.isActive ? 0 : 1)};
  transition: 1s;
`
const Inner = styled.div`
  display: flex;
  margin: 0 auto;
  max-width: 1100px;
  height: 46px;
  justify-content: space-between;

  @media (max-width: 1080px) {
    padding: 0 20px;
    width: 100%;
  }
`
const Left = styled.div`
  flex: 1;
  display: flex;
  align-items: center;
`
const Right = styled(Left)`
  flex: 0;
`
const HomeBtn = styled(Link)`
  margin-top: -2px;
`
const LogoTextArea = styled.div<cssState>`
  display: flex;
  align-items: center;
  opacity: ${props => (props.isActive ? 0 : 1)};
  transition: 2s;
`
const Bar = styled.div`
  margin: 0 15px;
  width: 1px;
  height: 16px;
  border-radius: 2px;
  background-color: ${color.border};
`
const LogoText = styled.strong`
  color: ${color.ink};
`
const SearchButton = styled.button`
  display: flex;
  align-items: center;
  margin-right: 16px;
  color: ${color.muted};

  &:hover {
    color: ${color.accent};
  }
`
const SelectedCate = styled.div`
  display: flex;
  position: relative;
  justify-content: flex-end;

  &:hover .HoverCateArea {
    display: flex;
  }
`
const SelectedCateText = styled.div`
  color: ${color.white};
  background-color: ${color.accent};
  padding: 6px 24px;
  border-radius: 999px;
  font-weight: 700;
  cursor: pointer;
`
const HoverCateArea = styled.div`
  z-index: 1;
  display: none;
  position: absolute;
  top: 100%;
  right: -20px;
  width: 300px;
  border: 1px solid ${color.border};
  border-radius: 12px;
  background-color: ${color.white};
  box-shadow: 0 8px 24px ${color.shadow};
`
const HoverCateList = styled.div`
  float: left;
  padding: 15px;
  width: 100%;
  height: 100%;
`
const HoverCateItem = styled.div`
  display: inline-block;
  margin-bottom: 10px;
`
const HoverCate = styled(({ active, ...props }: GatsbyLinkProps) => (
  <Link {...props} />
))`
  margin-top: 8px;
  margin-right: 10px;
  color: ${({ active }) => (active ? color.accent : color.muted)};
  font-weight: ${({ active }) => (active ? 700 : 400)};

  &:hover {
    color: ${color.accent};
    text-decoration: underline;
  }
`

const HoverCateText = styled.strong``

interface HeaderProps {
  isIntro: boolean
}

const Header = ({ isIntro = false }: HeaderProps) => {
  const { edges } = useGetCategories()
  const categoryList = useFormatCategory(edges)
  const selectedCategory = useSelectedCategory(
    typeof window !== 'undefined' ? window.location.search : '',
  )
  const [isSearchOpen, setIsSearchOpen] = useState<boolean>(false)

  return (
    <Wrap isActive={isIntro}>
      <Inner>
        <Left>
          <HomeBtn to="/">
            <FontAwesomeIcon
              icon={faHouseChimney}
              size={'lg'}
              color={color.ink}
            />
          </HomeBtn>
          <LogoTextArea isActive={isIntro}>
            <Bar />
            <LogoText>이해를 위한 기술블로그</LogoText>
          </LogoTextArea>
        </Left>
        <Right>
          <SearchButton
            onClick={() => setIsSearchOpen(true)}
            aria-label="검색 열기"
          >
            <FontAwesomeIcon icon={faMagnifyingGlass} />
          </SearchButton>
          <SelectedCate>
            <SelectedCateText>{selectedCategory}</SelectedCateText>
            <HoverCateArea className="HoverCateArea">
              <HoverCateList>
                {Object.entries(categoryList).map(cate => {
                  return (
                    <HoverCateItem key={cate[0]}>
                      <HoverCate
                        to={`/?category=${cate[0]}`}
                        active={cate[0] === selectedCategory}
                      >
                        <HoverCateText>
                          {cate[0]}({cate[1]})
                        </HoverCateText>
                      </HoverCate>
                    </HoverCateItem>
                  )
                })}
              </HoverCateList>
            </HoverCateArea>
          </SelectedCate>
        </Right>
      </Inner>
      <SearchModal
        isOpen={isSearchOpen}
        onClose={() => setIsSearchOpen(false)}
      />
    </Wrap>
  )
}

export default Header
